// CSD_RATIONALE_BEGIN
// Base: attempt 2 (best, 40.8%) — SafeRepetitionPenaltyStep(4.0) with closeReserve=80.
// Attempts 11-13 showed that per-span step guards reliably regress accuracy: they
// abort legitimate longer spans by forcing CloseSpanWithinBudget prematurely.
//
// Root cause of the unclosed-span failure mode:
//   The model generates Python comparison operators (== !=) inside spans; the
//   parser accepts them. After a few ! tokens, SafeRepetitionPenaltyStep penalises
//   every useful continuation token (they all appear in `generated`), so the LM's
//   top unmasked token becomes eosToken. The main loop then breaks on EOS while
//   the span is still open — producing `final_span_unclosed` failures.
//   CloseSpanWithinBudget is NOT triggered because `remaining > closeReserve` at
//   that point (avg generation is ~132 tokens, well below the 820-step threshold).
//
// Fix: EOS rescue inside open spans.
//   When SafeRepetitionPenaltyStep returns eosToken while insideConstrainedOut,
//   call CloseSpanWithinBudget with the remaining budget BEFORE breaking.
//   CloseSpanWithinBudget tracks the longest complete prefix across all generated
//   tokens (including the pre-EOS ! tokens), so it rolls back to the last valid
//   complete expression and emits >>. No per-span guard needed.
//
// No span-step guard: confirmed harmful in attempts 12-13; removed entirely.
//
// Guidance: close to attempt 2, adding explicit prohibition of comparison operators
//   (the source of ! loops) and emphasising int() for whole-number results.
//   Kept ** for exponentiation since removing it (attempt 13) regressed results.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 — parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   (remaining <= closeReserve, inside span — CloseSpanWithinBudget):
//     Postcondition: insideOut ==> parser.IsValidPrefix(currentOut).
//     Closed path (ci=false): implication vacuous. Open path: direct postcondition. ✓
//
//   (outside span — UnconstrainedStep):
//     If RenderedEndsWith triggers, we set currentConstrainedOut := [], and
//     IsValidPrefix([]) holds by the method precondition. Otherwise
//     insideConstrainedOut stays false (vacuous). ✓
//
//   (IsCompletePrefix branch — CloseConstrainedSpan):
//     Sets insideConstrainedOut := false; implication vacuously true. ✓
//
//   (constrained step, non-EOS — SafeRepetitionPenaltyStep + AppendConstrainedToken):
//     SafeRepetitionPenaltyStep hard-masks to parser-valid tokens plus EOS.
//     AppendConstrainedToken postcondition: parser.IsValidPrefix(currentOut). ✓
//
//   (constrained step, EOS — rescue CloseSpanWithinBudget):
//     EOS not appended to generated or currentConstrainedOut.
//     CloseSpanWithinBudget postcondition: insideOut ==> parser.IsValidPrefix(currentOut). ✓
//     If steps = maxSteps when EOS fires (guard `steps < maxSteps` fails): impossible
//     in this branch because remaining > closeReserve >= 1 before the step, so after
//     steps += 1 we still have steps < maxSteps. Guard always passes; rescue runs. ✓
//
//   (final cleanup — CloseSpanWithinBudget): same postcondition argument. ✓
//
// Invariant 2 — progress:
//   |generated| <= |generatedPrefix| + steps
//
//   (remaining <= closeReserve, s = steps_before):
//     CloseSpanWithinBudget(remaining): |cg| <= |generated| + remaining
//       <= |generatedPrefix| + s + (maxSteps - s) = |generatedPrefix| + maxSteps.
//     steps := maxSteps: |generated| <= |generatedPrefix| + maxSteps = |generatedPrefix| + steps. ✓
//
//   (outside): steps += 1; at most one token appended to generated. ✓
//   (IsCompletePrefix): steps += 1; CloseConstrainedSpan appends at most one >>. ✓
//   (constrained step, non-EOS): steps += 1; AppendConstrainedToken appends one token. ✓
//
//   (constrained step, EOS, s = steps_before):
//     steps = s + 1. generated unchanged before rescue.
//     |generated| <= |generatedPrefix| + s.
//     rescueBudget = maxSteps - (s+1).
//     CloseSpanWithinBudget: |cg| <= |generated| + rescueBudget
//       <= |generatedPrefix| + s + maxSteps - s - 1 = |generatedPrefix| + maxSteps - 1.
//     steps := maxSteps: |cg| <= |generatedPrefix| + maxSteps - 1 < |generatedPrefix| + maxSteps
//       = |generatedPrefix| + steps. ✓
//
//   (final cleanup, s = steps):
//     |cg| <= |generated| + (maxSteps - s) <= |generatedPrefix| + s + maxSteps - s
//       = |generatedPrefix| + maxSteps.
//     steps := maxSteps: |generated| <= |generatedPrefix| + maxSteps = |generatedPrefix| + steps. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve the problem step by step. " +
  "Wrap EVERY intermediate symbolic expression in << >> delimiters as you work. " +
  "For the final answer, write: The final answer is <<symbolic expression>>. " +
  "Inside << >> use ONLY: numbers, problem variables, +, -, *, /, //, %, **, (), int(). " +
  "Use int() when the result must be a whole number (counts, items, people, days). " +
  "Use // for integer (floor) division. Use ** for exponentiation. " +
  "Use the exact variable names given in the problem — never substitute numbers for variables. " +
  "Do not write == != > < >= <= inside << >>. " +
  "Do not write if/else or ternary expressions inside << >>.");

var closeReserve: nat := 80;
var steps: nat := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var remaining: nat := maxSteps - steps;

  if insideConstrainedOut && remaining <= closeReserve {
    // Budget running low inside a span: force-close dead-end-aware
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, remaining
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := maxSteps;
    break;
  } else if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if RenderedEndsWith(generated, "<<") {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  } else {
    // Constrained generation with repetition penalty to discourage ! loops
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.SafeRepetitionPenaltyStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, generated, 4.0, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      // EOS inside an open span: rescue by closing with remaining budget
      // (remaining > closeReserve before this step, so steps < maxSteps here)
      if steps < maxSteps {
        var rescueBudget: nat := maxSteps - steps;
        var cg, ci, cc := helpers.CloseSpanWithinBudget(
          lm, parser, prompt, generated, currentConstrainedOut, eosToken, rescueBudget
        );
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
        steps := maxSteps;
      }
      break;
    } else {
      var ag, ai, ac := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
    }
  }
}

// Final cleanup: close any remaining open span with whatever budget is left
if insideConstrainedOut && steps < maxSteps {
  var remaining: nat := maxSteps - steps;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, remaining
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := maxSteps;
}

cost := steps;

